AssessmentQuestion _q(int id, String text, Map<GiftKey, double> weights, {bool reverse = false}) {
  return AssessmentQuestion(
    id: 'q$id',
    text: text,
    weights: weights.entries
        .map((entry) => QuestionGiftWeight(gift: entry.key, weight: entry.value, reverseScored: reverse))
        .toList(),
  );
}

final careers = _careerRecords.map(_careerFromRecord).toList();

Career _careerFromRecord(_CareerRecord record) {
  final weights = {for (final gift in GiftKey.values) gift: 20};
  for (var i = 0; i < record.gifts.length; i++) {
    weights[record.gifts[i]] = 95 - (i * 13);
  }
  return Career(
    id: record.title.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '-').replaceAll(RegExp(r'-$'), ''),
    title: record.title,
    category: record.category,
    description: record.description,
    salaryLow: record.salaryLow,
    salaryHigh: record.salaryHigh,
    educationRequirement: record.education,
    responsibilities: record.responsibilities,
    environment: record.environment,
    interests: record.interests,
    values: record.values,
    giftWeights: weights,
  );
}

class _CareerRecord {
  const _CareerRecord(this.title, this.category, this.description, this.salaryLow, this.salaryHigh, this.education, this.gifts, this.interests, this.values, this.environment);

  final String title;
  final String category;
  final String description;
  final int salaryLow;
  final int salaryHigh;
  final String education;
  final List<GiftKey> gifts;
  final List<String> interests;
  final List<String> values;
  final String environment;

  List<String> get responsibilities => [
        'Guide people or projects toward meaningful outcomes',
        'Communicate clearly with stakeholders and teammates',
        'Solve practical problems with care and consistency',
      ];
}

